// ============================================
// CONFIGURACIÓN: Mapeo de videos a misiones
// ============================================
const missionVideoMapping = {
  'agenda': ['CAPACITACION_CALIDAD_MODULO AGENDA', 'AGENDA'],
  'catalogo': ['CATALOGO_CREAR', 'CATALOGO_EDITAR', 'CATALOGO'],
  'inventario': ['INVENTARIO_TIPOS', 'INVENTARIO_AJUSTES', 'INVENTARIO'],
  'pos': ['POS', 'PUNTO_VENTA', 'FACTURACION'],
  'clientes': ['CLIENTES', 'CRM'],
  'reportes': ['REPORTES', 'INFORMES'],
  'repaso': ['REPASO_', 'REVISION'] // Videos que empiezan con REPASO_
};

// ============================================
// FUNCIONES AUXILIARES
// ============================================

function mapVideoToMission(fileName, path) {
  const name = fileName.toUpperCase();

  // Buscar en patrones definidos
  for (const [mission, patterns] of Object.entries(missionVideoMapping)) {
    for (const pattern of patterns) {
      if (name.includes(pattern)) {
        return mission;
      }
    }
  }

  // Mapeo por path si no se encuentra en nombre
  if (path) {
    const pathLower = path.toLowerCase();
    if (pathLower.includes('agenda')) return 'agenda';
    if (pathLower.includes('catalogo')) return 'catalogo';
    if (pathLower.includes('inventario')) return 'inventario';
    if (pathLower.includes('pos')) return 'pos';
    if (pathLower.includes('clientes')) return 'clientes';
    if (pathLower.includes('reportes')) return 'reportes';
  }

  return 'general';
}

function cleanTitle(filename) {
  // Remover extensión y timestamp
  return filename
    .replace(/\.(mp4|avi|mov|mkv|webm)$/i, '')
    .replace(/-\d{8}_\d{6}-Grabación de la reunión/g, '')
    .replace(/-Grabación de la reunión/g, '')
    .replace(/CAPACITACION_CALIDAD_MODULO /g, '')
    .replace(/_/g, ' ')
    .trim();
}

function extractDuration(filename) {
  // Aquí podrías extraer duración real si está en el nombre
  // Por ahora retorna estimado
  return '10-15 min';
}

function determineContentType(filename, module) {
  const name = filename.toLowerCase();

  // Tipos específicos
  if (name.includes('capacitacion')) return 'capacitacion';
  if (name.includes('tutorial')) return 'tutorial';
  if (name.includes('demo')) return 'demo';
  if (name.includes('repaso')) return 'repaso';
  if (name.includes('revision')) return 'repaso';

  // Determinar por módulo
  if (module) {
    const moduleLower = module.toLowerCase();
    if (moduleLower.includes('agenda')) return 'mision';
    if (moduleLower.includes('catalogo')) return 'mision';
    if (moduleLower.includes('inventario')) return 'mision';
    if (moduleLower.includes('pos')) return 'mision';
  }

  return 'general';
}

function generateThumbnailUrl(videoUrl, title) {
  // Genera thumbnail con título del video
  const encodedTitle = encodeURIComponent(title);
  return `https://placehold.co/1280x720/4f46e5/ffffff?text=${encodedTitle}`;
}

function estimateSize(type) {
  // Estimación genérica basada en tipo
  return '~50-100 MB';
}

function calculatePriority(fileName, modifiedDate) {
  // Calcular prioridad basada en tipo de contenido y fecha
  let priority = 50; // Prioridad base

  const name = fileName.toLowerCase();

  // Incrementar prioridad para ciertos tipos
  if (name.includes('capacitacion')) priority += 20;
  if (name.includes('repaso')) priority += 30;
  if (name.includes('nuevo') || name.includes('actualizado')) priority += 15;

  // Incrementar prioridad para videos recientes (últimos 30 días)
  const daysSinceModified = (Date.now() - new Date(modifiedDate).getTime()) / (1000 * 60 * 60 * 24);
  if (daysSinceModified < 7) priority += 25;
  else if (daysSinceModified < 30) priority += 10;

  return Math.min(priority, 100); // Máximo 100
}

